demo.program:
// NOS3 idea demo (simulated model)
console.log('real flight SW + simulated HW');
console.log('NOS3: test like a flagship');

// NOS Engine demo (simulated model)
var buses=['I2C','SPI','UART'];
for(var i=0;i<buses.length;i++){console.log('bus up: '+buses[i]);}
console.log('NOS Engine routing');

// Sim HW demo (simulated model)
var hw=['EPS','radio','wheels','GPS'];
for(var i=0;i<hw.length;i++){console.log('sim '+hw[i]+' responding');}
console.log(hw.length+' boxes simulated');

// cFS-in-NOS3 demo (simulated model)
console.log('cFS apps: HK, SCH running on NOS3');
console.log('flight config under test');

// Dynamics loop demo (simulated model)
for(var i=0;i<3;i++){console.log('step '+i+': sense -> GNC -> actuate');}
console.log('loop closed through flight SW');

// Ground demo (simulated model)
console.log('uplink: CMD sent, telemetry received');
console.log('ground loop exercised');

// DITL demo (simulated model)
var tl=['deploy','burn','payload','eclipse'];
for(var i=0;i<tl.length;i++){console.log('T+'+i+'h: '+tl[i]+' OK');}
console.log('day-in-the-life passed');

// Fault demo (simulated model)
console.log('inject: wheel stuck -> FDIR safe mode');
console.log('fault handled (simulated)');

// Timing demo (simulated model)
var slots=10, miss=0;
for(var i=0;i<slots;i++){if((i*13)%17===0)miss++;}
console.log('slots '+slots+' missed '+miss);
console.log(miss===0?'TIMING MET':'finding filed');

// Smallsat demo (simulated model)
console.log('CubeSat: 400 HIL cases passed');
console.log('small, but tested');

// Maturation demo (simulated model)
var steps=['NOS3 sim','FlatSat','flight'];
for(var i=0;i<steps.length;i++){console.log('stage '+(i+1)+': '+steps[i]);}
console.log('maturation path walked');

// Regression demo (simulated model)
var tests=240, fail=0;
console.log(tests+' tests, '+fail+' failures');
console.log('regression green');

// Power demo (simulated model)
var soc=80;
for(var i=0;i<4;i++){soc+=[5,-12,5,-3][i];console.log('orbit '+i+': SoC '+soc+'%');}
console.log('power budget closes');

// Link demo (simulated model)
var passes=[['06:12',95],['08:47',88]];
for(var i=0;i<passes.length;i++){console.log('pass '+passes[i][0]+': '+passes[i][1]+'% success');}
console.log('link proven');

// Campaign demo (simulated model)
var c=['build','DITL','faults','timing','regress','fly'];
for(var i=0;i<c.length;i++){console.log((i+1)+'. '+c[i]);}
console.log('NOS3 campaign complete');
